import React, { useEffect, useState, useRef } from "react";
import axios from "axios";
import { Client } from "@stomp/stompjs";
import SockJS from "sockjs-client";

export default function LudoBoard() {
  const [boardState, setBoardState] = useState(null);
  const [diceValue, setDiceValue] = useState(null);
  const [status, setStatus] = useState("");
  const stompClientRef = useRef(null);
  const autoCancelRef = useRef(null);
  const sessionId = localStorage.getItem("currentSessionId");

  // WebSocket কানেকশন
  useEffect(() => {
    const token = localStorage.getItem("authToken");
    const socket = new SockJS(`http://localhost:8080/ludo-ws?token=${token}`);
    const client = new Client({
      webSocketFactory: () => socket,
      onConnect: () => {
        client.subscribe(`/topic/game/${sessionId}`, (message) => {
          const state = JSON.parse(message.body);
          setBoardState(state);
        });
      },
    });
    client.activate();
    stompClientRef.current = client;
    return () => client.deactivate();
  }, [sessionId]);

  // ডাইস রোল
  const rollDice = async () => {
    const token = localStorage.getItem("authToken");
    const res = await axios.post(
      `http://localhost:8080/api/match/rollDice/${sessionId}`,
      {},
      { headers: { Authorization: `Bearer ${token}` } }
    );
    const dice = Math.floor(Math.random() * 6) + 1;
    setDiceValue(dice);
    resetAutoCancel();
  };

  // ৬০ সেকেন্ড ইনঅ্যাক্টিভ হলে অটো-ক্যানসেল
  const resetAutoCancel = () => {
    if (autoCancelRef.current) clearTimeout(autoCancelRef.current);
    autoCancelRef.current = setTimeout(async () => {
      setStatus("❌ ৬০ সেকেন্ডে ডাইস চালানো হয়নি, ম্যাচ ক্যানসেল");
      await axios.get(`http://localhost:8080/api/match/status/${sessionId}`);
    }, 60000);
  };

  return (
    <div>
      <h2>🎯 Ludo Game</h2>
      {status && <p>{status}</p>}
      {boardState && <pre>{JSON.stringify(boardState, null, 2)}</pre>}
      <button onClick={rollDice}>🎲 ডাইস চালাও</button>
      {diceValue && <p>আপনি {diceValue} পেয়েছেন</p>}
    </div>
  );
}
